-- The games' starting content (2026-11-18). Inserted once, into empty tables; from then on it's edited on the edit page.
-- * game_questions: Taea's master set of Nov 16 (shown), with her two fixes in. Question 13 was short answer and is now
--   multiple choice (her call, Nov 18), and the Baby Steps starter questions the master set didn't cover are added (her
--   call, Nov 18); those are drafts, hidden until she checks them.
-- * match_pairs: her 28 pairs of dogs and cats, and the 3 proposed goldfish pairs. All hidden until she has checked each
--   one and its photo. Pairs 1 to 6 start with the free-license photos from her card files (site/assets/games/).
-- * game_situations: the 12 Go on Green starters (Nov 8) and 6 more, each with a line for every light. Drafts, hidden.

insert into public.game_questions (level, kind, question, choices, answer, hint, why, reward, published, sort)
select * from (values
  (1, 'tf', 'Dogs can eat chocolate.', '["True", "False"]'::jsonb, 2, null, 'Regular human chocolate can make dogs very sick. Only special dog-safe chocolate is OK.', null, true, 10),
  (1, 'tf', 'Pets need a clean, cozy place to sleep where they feel safe.', '["True", "False"]'::jsonb, 1, null, null, null, true, 20),
  (1, 'tf', 'It is okay to bother a dog while they are eating their dinner.', '["True", "False"]'::jsonb, 2, null, 'Dogs like peace and quiet while they eat!', null, true, 30),
  (1, 'tf', 'Small pets like hamsters and guinea pigs need "gentle hands" when being held.', '["True", "False"]'::jsonb, 1, null, null, null, true, 40),
  (1, 'mc', 'If an animal backs away, what should you do?', '["Make it accept the pets.", "Back off until he''s ready.", "Stand on your head."]'::jsonb, 2, null, null, null, true, 50),
  (1, 'mc', 'A doctor who takes care of pets is called...', '["Veterinarian", "Oncologist", "Paleontologist"]'::jsonb, 1, null, null, null, true, 60),
  (1, 'mc', 'What should you fill a dog''s bowl with every day?', '["Water", "Orange juice", "Milk"]'::jsonb, 1, null, null, null, true, 70),
  (1, 'mc', 'Which of these human foods is safe for dogs to eat?', '["Plain carrots", "Grapes", "Chocolate"]'::jsonb, 1, null, null, null, true, 80),
  (1, 'mc', 'What should you do before petting a dog you don''t know?', '["Run up and hug them", "Ask the owner first", "Pull their tail"]'::jsonb, 2, null, null, null, true, 90),
  (1, 'mc', 'What does it usually mean when a dog has a loose, wiggly body and a wagging tail?', '["They are fast asleep", "They are very angry", "They are happy and friendly"]'::jsonb, 3, null, null, null, true, 100),
  (1, 'mc', 'If a pet walks away or hides under a bed, what are they telling you?', '["\"Come chase me!\"", "\"I need some quiet space right now.\"", "\"I want a bath.\""]'::jsonb, 2, null, null, null, true, 110),
  (1, 'mc', 'Pinned ears mean the animal is...', '["Angry", "Anxious", "Happy"]'::jsonb, 2, null, null, null, true, 120),
  (1, 'mc', 'Why is it important to ask before you pet someone''s dog?', '["So you can pet them faster", "The owner knows if their dog is friendly, scared, in training, or not feeling well", "Dogs only like people with good manners"]'::jsonb, 2, null, 'Only the owner knows how their dog is feeling today, so we always ask first.', null, false, 130),
  (2, 'mc', 'If a dog yawns, licks their lips, or turns their head away when you try to hug them, what are they usually saying?', '["They are sleepy and want a nap", "They feel stressed or uncomfortable", "They are asking for a treat"]'::jsonb, 2, null, null, 'Great catch! Yawning and lip-licking are subtle "calming signals" dogs use to show they need a little space.', true, 140),
  (2, 'mc', 'Which of these common fruits is toxic to dogs and can hurt their kidneys?', '["Blueberries", "Grapes and raisins", "Seedless watermelon"]'::jsonb, 2, null, null, 'Spot on! Even a small amount of grapes or raisins can be very dangerous for dogs.', true, 150),
  (2, 'mc', 'Why is it important to use a harness instead of clipping a leash to a collar for small dogs or dogs that pull hard?', '["It makes them run faster", "It protects their throat and neck from injury", "It keeps their fur clean"]'::jsonb, 2, null, null, 'Correct! A harness spreads pressure across the chest and shoulders so it doesn''t hurt their windpipe.', true, 160),
  (2, 'mc', 'What does "mental enrichment" mean for a pet?', '["Teaching them how to read", "Giving them puzzles, sniffing games, and toys to keep their brain busy", "Letting them watch cartoons all day"]'::jsonb, 2, null, null, 'Awesome! Sniffing and puzzle feeders tire out a dog''s brain just as much as a long walk tires out their legs.', true, 170),
  (2, 'mc', 'Why should you never leave a dog inside a parked car on a warm day, even with the windows cracked?', '["They might honk the horn", "Cars trap heat and can reach dangerous temperatures in just a few minutes", "They will get bored"]'::jsonb, 2, null, null, 'You got it! Dogs can''t sweat like humans do, so they can overheat very quickly in a parked car.', true, 180),
  (2, 'scenario', 'You are at the park and see a friendly-looking dog tied up outside a shop while their owner is inside. The dog''s tail is wagging slowly. What should you do?', '["Walk up slowly and pet the top of their head so they don''t feel lonely.", "Untie the leash so they can come play on the grass.", "Leave the dog alone and do not approach without the owner there."]'::jsonb, 3, 'Even a dog with a wagging tail can feel trapped or nervous when tied up alone without their owner to say it''s okay!', null, 'Boss move! Never approach a dog tied up alone — without their owner present, they might feel cornered and scared.', true, 190),
  (2, 'scenario', 'Your dog just grabbed a sock from the laundry basket and is running away with it like a game of keep-away. What is the safest way to get it back?', '["Chase them around the house yelling \"Drop it!\" and try to pry their mouth open.", "Stay calm, grab a high-value treat or favorite toy, and trade with them.", "Let them chew on it until they get bored."]'::jsonb, 2, 'Chasing a dog makes them think it''s a fun game, and grabbing things from their mouth can cause them to swallow the sock fast!', null, 'Genius! "Trading up" teaches your dog that giving you things earns them an even better reward, keeping them safe from swallowing dangerous items.', true, 200),
  (2, 'scenario', 'A friend comes over to play and wants to meet your shy rescue dog. Your dog walks over to their crate or bed and lies down inside. What should you tell your friend?', '["\"That''s their safe zone, so let''s give them space and let them come out when they''re ready.\"", "\"Reach inside and gently pull them out so they can say hi.\"", "\"Clap your hands loudly so they know we want to play.\""]'::jsonb, 1, 'A pet''s bed or crate is like their private bedroom — nobody likes someone reaching into their safe space uninvited!', null, 'True animal guardian! Respecting a pet''s safe zone builds huge trust and helps shy animals feel brave later on.', true, 210),
  (2, 'scenario', 'You notice a neighbor''s dog has been barking nonstop in a fenced yard, and their water bowl is completely empty on a hot afternoon. What is the best action to take?', '["Climb over the fence to fill the bowl yourself.", "Throw snacks over the fence to make them feel better.", "Tell a trusted adult right away so they can knock on the neighbor''s door or call for help."]'::jsonb, 3, 'Never enter a stranger''s yard where an unfamiliar dog is protective of their territory — always get a grown-up to help safely!', null, 'Heroic choice! Getting a trusted adult keeps you safe while making sure the dog gets the water and help they need.', true, 220),
  (2, 'scenario', 'You are petting a dog on their chest, and they suddenly freeze, close their mouth tightly, and show the whites of their eyes ("whale eye"). What is your next move?', '["Keep petting them softly to help them relax.", "Stop petting immediately, stand up slowly, and step back to give them space.", "Give them a big hug around their neck."]'::jsonb, 2, 'When a dog goes stiff like a statue and shows the whites of their eyes, they are giving a clear warning that they have had enough!', null, 'Expert level! Recognizing early "stop" signals like freezing and whale eye keeps everyone safe and shows deep respect for how animals communicate.', true, 230),
  (3, 'mc', 'What is a microchip, and how does it help a lost pet?', '["It is a tiny GPS tracker that shows their location on a phone map", "It is a tiny ID tag placed under the skin that a vet or shelter can scan", "It is a battery that powers their collar"]'::jsonb, 2, null, null, 'Nailed it! A microchip doesn''t have GPS, so it''s super important to keep your contact info updated in the registry!', true, 240),
  (3, 'mc', 'Why do veterinarians recommend regular heartworm prevention medicine for dogs?', '["To keep their fur shiny", "To protect them from dangerous parasites spread by mosquito bites", "To help them sleep better at night"]'::jsonb, 2, null, null, 'Smart thinking! Just one bite from an infected mosquito can pass heartworms to a dog, so monthly prevention is key.', true, 250),
  (3, 'mc', 'What does "positive reinforcement" training mean?', '["Yelling \"No!\" louder until the dog listens", "Rewarding good behavior with treats, praise, or play so the dog wants to repeat it", "Putting the dog in time-out every time they bark"]'::jsonb, 2, null, null, 'Bingo! Animals learn fastest and build stronger trust when they are rewarded for making good choices.', true, 260),
  (3, 'mc', 'If a dog''s tail is tucked tight between their legs and their ears are pinned flat back, how are they feeling?', '["Excited to play fetch", "Scared or anxious", "Ready to take a nap"]'::jsonb, 2, null, null, 'Right on! Tucked tails and pinned ears are clear signs a dog is frightened and needs to feel safe.', true, 270),
  (3, 'mc', 'Why is it important to adopt or research carefully before bringing a pet home?', '["Pets only live for a few months", "Pets are a lifelong commitment that need time, money, and care for 10 to 15+ years", "You can return them whenever you get busy"]'::jsonb, 2, null, null, 'True guardian mindset! Being prepared ensures a pet stays in a loving home their whole life.', true, 280),
  (1, 'mc', 'Your dog has been playing outside and is panting. What does she need?', '["A nap in the sun", "Water and shade", "A big meal right now"]'::jsonb, 2, null, 'Panting means she''s hot. Water and shade help her cool down.', null, false, 290),
  (1, 'tf', 'It''s okay to pull a cat''s tail.', '["True", "False"]'::jsonb, 2, null, 'Tails are part of the cat. Pulling hurts and scares them. Gentle hands!', null, false, 300),
  (2, 'tf', 'You should wake a sleeping dog to play with it.', '["True", "False"]'::jsonb, 2, null, 'Sleeping animals need rest. We wait until they wake up and want to play.', null, false, 310),
  (2, 'tf', 'A wagging tail always means a dog is happy.', '["True", "False"]'::jsonb, 2, null, 'A stiff body with a wagging tail can mean the dog is worried or warning you. The whole body tells the story.', null, false, 320),
  (3, 'tf', 'If a dog shows you its belly, it always wants a belly rub.', '["True", "False"]'::jsonb, 2, null, 'Sometimes a belly-up dog is scared and saying "please don''t hurt me." Look at the rest of the body first.', null, false, 330),
  (3, 'mc', 'Your rabbit thumps its back foot hard. What is it saying?', '["It''s happy", "It''s warning of danger", "It wants food"]'::jsonb, 2, null, 'Rabbits thump to warn others that something scary is near.', null, false, 340),
  (3, 'tf', 'Cats only purr when they are happy.', '["True", "False"]'::jsonb, 2, null, 'Cats also purr when they''re scared, hurt or unwell. Purring can be a way they calm themselves.', null, false, 350)
) v(level, kind, question, choices, answer, hint, why, reward, published, sort)
where not exists (select 1 from public.game_questions);

insert into public.match_pairs (level, title, species, tile, cue, question, choices, answer, reward, photo_url, published, sort)
select * from (values
  (1, 'The Play Bow', 'Dog', 'A dog with their front elbows down on the ground, rear end up in the air, and a wagging tail.', null, 'You matched the Play Bow! What is this dog asking for?', '["\"Please leave me alone.\"", "\"Let''s play together!\"", "\"I am ready for bedtime.\""]'::jsonb, 2, 'Yes! A play bow is a dog''s favorite way to invite you or another pet to have fun.', 'assets/games/pair-01-play-bow.jpg', false, 10),
  (1, 'The Slow Blink', 'Cat', 'A relaxed cat sitting comfortably with half-closed, sleepy eyes.', null, 'You matched the Slow Blink! What does it mean when a cat blinks slowly at you?', '["They have something in their eye.", "They trust you and feel safe and happy.", "They are getting ready to hiss."]'::jsonb, 2, 'Purr-fect! A slow blink is like a "kitty kiss" that shows they feel safe around you.', 'assets/games/pair-02-slow-blink.jpg', false, 20),
  (1, 'The Belly-Up Snooze', 'Dog or Cat', 'A pet fast asleep on their back with all four paws relaxed in the air.', null, 'You matched the Belly-Up Snooze! Why does a pet sleep with their belly showing?', '["They feel completely safe in their home.", "They want you to wake them up right away.", "They are cold and need a sweater."]'::jsonb, 1, 'Spot on! Pets only show their bellies when they feel super comfortable, though it''s always best to let sleeping pets rest undisturbed!', 'assets/games/pair-03-belly-up-snooze.jpg', false, 30),
  (1, 'The Puffed-Up Tail', 'Cat', 'A cat with an arched back and a tail puffed up like a big bottle brush.', null, 'You matched the Puffed-Up Tail! How is this cat feeling?', '["Excited for dinner", "Startled, scared, or trying to look bigger", "Ready for a belly rub"]'::jsonb, 2, 'Great job! Cats puff up their fur when something surprises or scares them, so it''s best to give them quiet space.', 'assets/games/pair-04-puffed-up-tail.jpg', false, 40),
  (1, 'The Tucked Tail', 'Dog', 'A dog standing low to the ground with their ears down and tail tucked tight under their belly.', null, 'You matched the Tucked Tail! What should you do when a dog looks like this?', '["Run over and give them a big hug.", "Stay calm, speak softly, and give them space.", "Loudly clap your hands."]'::jsonb, 2, 'Awesome kindness! A tucked tail means a dog feels nervous or shy, so giving them space helps them feel brave again.', 'assets/games/pair-05-tucked-tail.jpg', false, 50),
  (1, 'The Happy Wiggly Greeting', 'Dog', 'A dog with soft ears, an open happy mouth, and a tail wagging in wide, loose circles.', null, 'You matched the Wiggly Greeting! What is this dog telling you?', '["\"I am happy to see you!\"", "\"I am hiding from a loud noise.\"", "\"I am guarding my food bowl.\""]'::jsonb, 1, 'You got it! Loose, wiggly bodies and soft faces mean a dog is relaxed and friendly.', 'assets/games/pair-06-happy-greeting.jpg', false, 60),
  (1, 'The Happy Purr & Knead', 'Cat', 'A cat with relaxed whiskers gently pressing their front paws back and forth on a soft blanket ("making biscuits").', null, 'You matched Making Biscuits! Why do cats knead soft blankets with their paws?', '["They are trying to dig a hole.", "They feel super cozy, safe, and happy.", "Their paws are cold."]'::jsonb, 2, 'Purr-fect! Kneading is a comforting habit from when they were tiny kittens, showing they feel totally content.', null, false, 70),
  (1, 'The Playful Pounce Wiggle', 'Cat', 'A cat crouched low to the ground with wide eyes, wiggling their rear end while staring at a feather toy.', null, 'You matched the Pounce Wiggle! What is this cat getting ready to do?', '["Leap and catch their toy!", "Go to sleep for the night.", "Ask for a bath."]'::jsonb, 1, 'Spot on! That little wiggle helps cats balance their back legs right before they launch into playful pounce mode.', null, false, 80),
  (1, 'The Soft Head Tilt', 'Dog', 'A dog sitting with ears perked up and their head tilted curiously to one side.', null, 'You matched the Head Tilt! Why does a dog tilt their head like this?', '["Their neck is stuck.", "They are listening closely and trying to understand you.", "They are feeling angry."]'::jsonb, 2, 'Great job! Tilting their head helps dogs hear sounds better and see past their nose to read your face.', null, false, 90),
  (1, 'The Hissing Warning', 'Cat', 'A cat with flattened ears, an open mouth showing teeth, and whiskers pulled back.', null, 'You matched the Hissing Warning! What does a hiss mean?', '["\"Come pick me up right now!\"", "\"Stop! I feel scared or threatened — back away please.\"", "\"I want to play tag.\""]'::jsonb, 2, 'Smart thinking! A hiss isn''t a cat being mean — it''s their polite warning asking for space so nobody gets scratched.', null, false, 100),
  (1, 'The Full-Body Shake-Off', 'Dog', 'A dry dog shaking their whole body from head to tail as if they just got out of a bath.', null, 'You matched the Shake-Off! Why does a dry dog shake their whole body after a hug or a stressful moment?', '["To shake off extra tension and help themselves relax.", "Because they forgot they aren''t wet.", "To tell you they are hungry."]'::jsonb, 1, 'Nailed it! Just like taking a deep breath, a shake-off helps dogs reset their nervous system and feel calm again.', null, false, 110),
  (2, 'The Swishing Cat Tail', 'Cat', 'A cat sitting upright with a tense face and a tail thrashing quickly back and forth against the floor.', null, 'You matched the Swishing Tail! Unlike a happy dog, what does a fast-swishing tail mean on a cat?', '["They are super excited to be petted.", "They are getting annoyed or overstimulated — time to stop petting!", "They are fast asleep."]'::jsonb, 2, 'Huge difference! Dogs wag to say "hi," while a thumping cat tail means "I''ve had enough touches for right now."', null, false, 120),
  (2, 'The Stress Yawn & Lip Lick', 'Dog', 'A dog sitting still with ears slightly back, giving a big yawn and flicking their tongue over their nose even though they aren''t tired or eating.', null, 'You matched the Lip Lick & Yawn! What is this dog telling you?', '["\"I am starving for dinner!\"", "\"I feel a little nervous or uncomfortable right now.\"", "\"Please give me a tight hug.\""]'::jsonb, 2, 'Great eye! These are subtle "calming signals" dogs use when they feel stressed and want things to slow down.', null, false, 130),
  (2, 'The "Whale Eye" / Half-Moon Eye', 'Dog', 'A dog holding a bone, turning their head slightly away while looking sideways so you can see the white crescent of their eyes.', null, 'You matched Whale Eye! What should you do if a dog shows the whites of their eyes while guarding a toy or bone?', '["Step back right away and leave them alone with their treasure.", "Reach down and take the bone away.", "Put your face close to theirs."]'::jsonb, 1, 'Safe choice! Whale eye is a clear warning that a dog feels uncomfortable and worried someone might take their item.', null, false, 140),
  (2, 'The High, Stiff Flag Tail', 'Dog', 'A dog standing tall and frozen with their tail held straight up like a flagpole, wagging only the very tip rapidly.', null, 'You matched the Stiff Flag Tail! Does every wagging tail mean a dog is friendly?', '["Yes, all tail wags mean \"come pet me!\"", "No! A stiff body and high, tight wag means the dog is tense or on high alert.", "It means the dog wants to take a nap."]'::jsonb, 2, 'Pro level! Always look at the whole body — a loose, wiggly wag is friendly, while a stiff, frozen wag means "give space."', null, false, 150),
  (2, 'The Cat "Airplane Ears"', 'Cat', 'A cat crouching slightly with wide pupils and ears turned flat out to the sides like airplane wings.', null, 'You matched Airplane Ears! How is a cat feeling when their ears flatten out to the sides?', '["Ready to fly around the room playfully", "Worried, startled, or unsure about something nearby", "Completely relaxed and sleepy."]'::jsonb, 2, 'Right on! Ears flattened to the sides are a cat''s early sign of stress or fear — giving them space helps them calm down.', null, false, 160),
  (2, 'The Cat Belly Trap', 'Cat', 'A cat lying on their back with paws curled in and wide, alert eyes looking up.', null, 'You matched the Cat Belly Roll! When a cat rolls onto their back and shows their belly, what are they usually saying?', '["\"Please rub my tummy hard!\"", "\"I trust you enough to relax here, so let''s keep petting my head and cheeks instead.\"", "\"I am stuck and can''t roll over.\""]'::jsonb, 2, 'Purr-fect! Unlike dogs, most cats show their belly to say "I trust you," not to ask for a tummy rub — stick to chin and cheek scratches!', null, false, 170),
  (2, 'The Raised Paw / "Hover Paw"', 'Dog', 'A dog sitting or standing still with one front paw lifted slightly off the ground, ears slightly back, and a closed mouth.', null, 'You matched the Hover Paw! What does it mean when a dog lifts one front paw while standing still in a new place?', '["They are trying to shake hands with everyone.", "They are feeling unsure, cautious, or trying to figure out what is happening.", "Their paw is hurt and needs a bandage."]'::jsonb, 2, 'Great catch! A raised front paw (when not playing or injured) is a classic sign a dog is pausing to think and feels a little uncertain.', null, false, 180),
  (2, 'The Cat Question-Mark Tail', 'Cat', 'A cat walking toward you with their tail held straight up and curled gently at the very tip like a question mark.', null, 'You matched the Question-Mark Tail! What is this cat saying as they walk up to you?', '["\"I am lost and confused.\"", "\"Hello friend! I am happy to see you and open to saying hi.\"", "\"Stay away from my food bowl.\""]'::jsonb, 2, 'Awesome! A tall tail with a little hook at the tip is one of a cat''s friendliest greetings.', null, false, 190),
  (2, 'The Sniffing Ground Distraction', 'Dog', 'A dog on a walk suddenly stopping to sniff one blade of grass intensely while another dog walks past nearby.', null, 'You matched the Polite Ground Sniff! Why does a dog suddenly sniff the ground when another dog or person walks toward them?', '["They dropped a crumb earlier.", "They are showing polite manners and avoiding staring to keep things peaceful.", "They forgot how to walk."]'::jsonb, 2, 'Smart thinking! In dog language, staring is rude — sniffing the ground is a polite way to say, "I''m peaceful and no threat to you!"', null, false, 200),
  (3, 'The Submissive Grin', 'Dog', 'A dog greeting someone with low, wiggling hips, soft squinty eyes, flattened ears, and their front lips pulled up showing their front teeth.', null, 'You matched the Submissive Grin! Unlike an angry snarl, what does this toothy smile mean when paired with soft eyes and a low, wiggly body?', '["\"Get away from me right now!\"", "\"I''m a little nervous, please be gentle — I''m friendly!\"", "\"I have something stuck in my teeth.\""]'::jsonb, 2, 'Expert eye! Some dogs show their front teeth as an appeasement smile when they feel shy or excited — look at their soft, wiggly body to tell the difference from a stiff, angry snarl.', null, false, 210),
  (3, 'The Cat Bunting / Cheek Rub', 'Cat', 'A cat gently pressing and rubbing the side of their cheeks and forehead against a person''s hand or a chair leg.', null, 'You matched Cat Bunting! Why do cats rub their cheeks against people and furniture?', '["To leave happy scent markers that say \"You are part of my safe family.\"", "Because their face is always itchy.", "To wipe food off their whiskers."]'::jsonb, 1, 'Purr-fect! Cats have special scent glands on their cheeks — bunting means they are claiming you as safe, familiar, and trusted.', null, false, 220),
  (3, 'The Pilomotor Hackles / Raised Fur', 'Dog', 'A dog meeting another dog with a strip of fur standing straight up along the top of their shoulders and back.', null, 'You matched Raised Hackles! What does it mean when the fur along a dog''s back stands up?', '["The dog is definitely going to attack.", "The dog is feeling a big rush of excitement, surprise, or nervousness.", "The dog needs a haircut."]'::jsonb, 2, 'Pro level! Raised hackles are like human goosebumps — they happen automatically when a dog feels intense emotion, whether excited, startled, or unsure.', null, false, 230),
  (3, 'The "Sploot" / Frog-Leg Stretch', 'Dog', 'A pet lying flat on their tummy on a cool floor with both back legs stretched straight out behind them.', null, 'You matched the Sploot! Why do dogs stretch both back legs straight behind them on the floor?', '["Their back legs are broken.", "They are completely relaxed and cooling their belly against the floor.", "They are getting ready to dig under the rug."]'::jsonb, 2, 'Spot on! Only dogs with healthy, flexible hips who feel totally safe and comfortable will stretch out in a full sploot.', null, false, 240),
  (3, 'The Displacement Scratch', 'Dog', 'A dog in the middle of a training session or noisy room suddenly stopping to scratch their ear with a back foot for a few seconds.', null, 'You matched the Displacement Scratch! Why might a dog suddenly stop and scratch an itch right when you ask them to do something new?', '["They feel a little confused or pressured and are taking a quick mental break.", "They suddenly got fleas at that exact second.", "They are ignoring you on purpose to be stubborn."]'::jsonb, 1, 'Genius observation! Just like humans scratch their heads when thinking hard, dogs use quick "displacement" scratches to relieve mild stress or confusion.', null, false, 250),
  (3, 'The Cat Dilated "Saucer" Pupils', 'Cat', 'A cat sitting in a bright room with their black eye pupils expanded huge and round, covering almost the entire eye.', null, 'You matched Saucer Eyes! In a bright room, what do giant, round cat pupils usually tell you?', '["The cat is very sleepy.", "The cat is flooded with big energy — either playful hunting mode or sudden fear.", "The cat needs glasses."]'::jsonb, 2, 'Nailed it! In bright light, big pupils mean high adrenaline — check their ears and tail to see if they are ready to pounce on a toy or hiding from a scare!', null, false, 260),
  (3, 'The Dog "Hard Stare" / Freeze Over Food', 'Dog', 'A dog standing over their food bowl with a frozen body, closed mouth, and intense, unblinking eyes staring straight ahead.', null, 'You matched the Hard Stare! What is a dog communicating when they freeze completely and stare without blinking?', '["\"Please come take my bowl away.\"", "\"Stop right there — I am feeling protective and uncomfortable.\"", "\"I am waiting for a belly rub.\""]'::jsonb, 2, 'Critical safety skill! A frozen body and hard, unblinking stare are serious warning signs — always freeze, step back calmly, and leave the dog alone.', null, false, 270),
  (3, 'The Cat "Skin Ripple" / Twitching Back', 'Cat', 'A cat being petted down their spine whose lower back skin suddenly ripples and twitches while their ears flick back.', null, 'You matched the Back Skin Ripple! If a cat''s back skin twitches while you are petting them, what should you do?', '["Pet them faster and harder in that exact spot.", "Stop petting right away — their skin is feeling overstimulated and sensitive.", "Pick them up and carry them around."]'::jsonb, 2, 'Master level! Some cats get "petting-induced overstimulation" where gentle strokes suddenly feel ticklish or irritating — stopping at the first twitch keeps them happy!', null, false, 280),
  (1, 'Goldfish Gulping at the Surface', 'Goldfish', 'A goldfish at the top of the tank, mouth opening and closing at the water''s surface.', null, 'What should you do if a goldfish keeps gulping at the surface like this?', '["Tap on the glass to scare it back down.", "Tell a grown-up — the water might need more air.", "Drop in extra food right away."]'::jsonb, 2, 'Good catch! Gulping at the surface can mean the water is low on oxygen, so a grown-up should check the filter and the water.', null, false, 290),
  (1, 'Goldfish Hiding Behind the Plants', 'Goldfish', 'A goldfish tucked behind the plants at the back of the tank, fins held close.', null, 'Why is this goldfish hiding behind the plants?', '["It is playing hide-and-seek.", "It feels scared or stressed and wants some quiet.", "It is asleep."]'::jsonb, 2, 'Spot on! Hiding is how a scared fish says "I need space" — keep voices low and hands out of the tank.', null, false, 300),
  (1, 'Goldfish Zooming Happily', 'Goldfish', 'A goldfish swimming fast, happy loops around the tank with its fins spread wide.', null, 'How is this goldfish feeling?', '["Happy and healthy — zooming around means it feels good!", "Angry at the other fish.", "Lost and looking for the way out."]'::jsonb, 1, 'You got it! A goldfish that zips around with fins spread is feeling safe and full of energy.', null, false, 310)
) v(level, title, species, tile, cue, question, choices, answer, reward, photo_url, published, sort)
where not exists (select 1 from public.match_pairs);

insert into public.game_situations (level, species, situation, light, why, green_line, yellow_line, red_line, published, sort)
select * from (values
  (1, 'dog', 'A dog sleeping curled up in his bed.', 'red', 'He''s asleep. Waking him could scare him, and a scared dog might snap. Sleeping animals need their rest.', 'He looks snuggly, but waking him could scare him. Do you like being woken up?', 'Even going slowly could wake him. Would you like being woken from a nap?', 'You let him sleep. You feel best after a good rest too!', false, 10),
  (1, 'dog', 'A dog in a play bow: front down, bottom up, tail wagging loose.', 'green', 'A play bow means "Let''s play!" His whole body is loose and wiggly.', 'Yes! He''s inviting you to play, just like when a friend waves you over.', 'Look at his whole body. Is it loose and wiggly, or stiff and still? This one is saying yes!', 'Look again: bottom up, tail wagging, body loose. That''s a happy invitation to play.', false, 20),
  (1, 'cat', 'A cat hiding inside a box, with only her eyes peeking out.', 'red', 'Her hiding spot is her safe place. We never pull an animal out of where it feels safe.', 'She''s hiding because she wants to be left alone. Where do you go when you need quiet?', 'She''s in her safe spot. Would you want someone reaching into your blanket fort?', 'You gave her space. Everyone needs a cozy spot to feel safe, you too.', false, 30),
  (1, 'dog', 'A dog walking toward you with a loose body, soft eyes and a tail wagging wide.', 'green', 'Loose body, soft eyes, coming closer: she''s happy to see you. Let her come the rest of the way to you.', 'You noticed it! She''s coming to say hi, like a friend who''s happy to see you.', 'She''s choosing to come to you, with a loose, happy body. That''s a yes!', 'Look at her soft eyes and wiggly tail. She''s happy and asking to say hi.', false, 40),
  (2, 'dog', 'A dog eating from his food bowl.', 'red', 'Never go near an animal while it eats. Eating is always a red: we wait.', 'He might worry you''ll take his food. How would you feel if someone grabbed your snack?', 'Even slowly, it''s best to stay away while he eats. Would you like someone reaching for your plate?', 'Right! You wait until he''s done, just like you''d want to finish your dinner in peace.', false, 50),
  (2, 'dog', 'A dog standing still, watching you, ears up, body a little stiff.', 'yellow', 'He''s not sure yet. Slow down, make yourself small, and let him decide.', 'He''s not coming closer, and his body is a bit stiff. He hasn''t said yes yet.', 'You saw it! He''s unsure, so we pause, the way you''d wait before joining a game you don''t know.', 'Backing away is kind, but he isn''t saying no. He''s deciding. Pausing lets him choose.', false, 60),
  (2, 'cat', 'A cat with her ears laid flat back and her tail swishing.', 'red', 'Flat ears and a swishing tail mean she''s scared or upset. She needs space.', 'Her ears and tail are saying "no, thank you." How do you show people you need space?', 'Look at her ears. Flat ears are asking for space, not a slow hello.', 'You spotted it! Flat ears mean leave her be, like when you need a minute alone.', false, 70),
  (2, 'cat', 'A cat lying stretched out, slow-blinking at you.', 'green', 'A relaxed body and a slow blink mean she feels safe. Blink slowly back to say hello.', 'Yes! That slow blink is a cat smile. Try a slow blink back.', 'Her body is soft and she''s blinking slowly. That means she feels safe with you.', 'Look at her soft body and sleepy eyes. She''s saying she trusts you.', false, 80),
  (3, 'dog', 'A dog wagging his tail, but his body is stiff, he''s staring hard, and his mouth is closed.', 'red', 'A wagging tail doesn''t always mean happy. His body says stiff and staring, and the body wins.', 'Tails can fool us! Look at the rest of him. Is his body loose or stiff?', 'His tail is moving, but his body is stiff and staring. That''s a warning, so it''s a red.', 'Brilliant! You listened to his whole body, not just his tail.', false, 90),
  (3, 'dog', 'A dog licking his lips and yawning while a child reaches toward him.', 'red', 'Lip licking and yawning mean "I''m uncomfortable." He''s asking for space.', 'He''s not sleepy, he''s uncomfortable. How do you feel when someone gets too close?', 'His mouth is already saying something. Lip licking and yawning mean he wants the reaching to stop.', 'You heard him! Licking lips means "please stop," and you listened.', false, 100),
  (3, 'dog', 'A dog you''ve never met, standing alone in a yard.', 'red', 'You don''t know this dog. Dogs we don''t know are always a red until their owner says it''s okay.', 'We don''t know this dog''s name or how he feels. Would you hug someone you just met?', 'Even slowly, we don''t go near a dog we don''t know. Who should we ask first?', 'Exactly. A dog you don''t know is a red until a grown-up and the owner say yes.', false, 110),
  (3, 'dog', 'A dog meeting you for the first time, his owner beside him, sniffing the air with his ears up.', 'yellow', 'His owner said you can meet, but he''s still deciding. Stay calm and let him sniff.', 'His owner said yes, but he hasn''t decided yet. Let him sniff first.', 'Good waiting! You let him choose, like when you meet someone new and take your time.', 'His owner says it''s okay, so you can stay, calmly, and let him come to you.', false, 120),
  (1, 'cat', 'A cat purring and rubbing her cheek against your hand.', 'green', 'Cheek rubs and purring mean she likes you and feels safe. Gentle pets on her cheeks are perfect.', 'Yes! She''s saying "you''re my friend." That feels nice, doesn''t it?', 'She''s already come to you and is rubbing your hand. That''s a happy yes!', 'She chose to come to you and she''s purring. She''s saying yes to gentle pets.', false, 130),
  (1, 'dog', 'A puppy chewing his favorite toy in his bed.', 'red', 'He''s busy with something special. Reaching for a dog''s toy can make him worry you''ll take it.', 'He might think you want his toy. How would you feel if someone took yours?', 'Even slowly, reaching near his toy can worry him. Let him finish.', 'You let him enjoy it. You wouldn''t want someone grabbing your favorite toy either!', false, 140),
  (2, 'bunny', 'A bunny sitting very still, her ears pressed flat against her back.', 'red', 'A frozen bunny with flat ears is scared. Stay still and quiet, and give her space.', 'Sitting still can look calm, but her flat ears say she''s scared. Have you ever frozen when something scared you?', 'She''s not calm, she''s frozen with fear. Even a slow hello could scare her more.', 'You noticed she''s scared. Being quiet and giving space helps her feel safe.', false, 150),
  (2, 'cat', 'A cat walking up to you with her tail straight up and curled at the tip, like a question mark.', 'green', 'A tall tail with a curl at the tip is one of a cat''s friendliest hellos.', 'You got it! That question-mark tail means "Hello, friend!"', 'She''s walking right to you with a happy tail. She''s saying hi!', 'Look at that tall, curly tail. That''s a friendly hello, not a no.', false, 160),
  (3, 'dog', 'A dog lying on his back showing his belly, but his body is stiff and he''s licking his lips.', 'red', 'A belly isn''t always asking for rubs. A stiff body and lip licking mean he''s worried. Give him space.', 'Belly up doesn''t always mean "rub me." What is the rest of his body saying?', 'His belly is up, but his body is stiff and he''s licking his lips. He''s worried, so it''s a red.', 'Expert eyes! You saw the stiff body and lip licking, not just the belly.', false, 170),
  (3, 'cat', 'A cat purring on your lap, then her tail starts to twitch and the skin on her back ripples.', 'red', 'Twitching and rippling skin mean she''s had enough petting for now. Stop and let her rest.', 'Her purring started out happy, but her tail and skin are saying stop. Do you ever get tired of being tickled?', 'She''s still on your lap, but her twitching tail says "that''s enough." Time to stop petting.', 'You stopped at the first twitch. That''s how you keep a cat happy and trusting.', false, 180)
) v(level, species, situation, light, why, green_line, yellow_line, red_line, published, sort)
where not exists (select 1 from public.game_situations);
